#!/bin/sh
# Checks that the commit message follows Conventional Commits.
# Usage: commit.sh <commit-message-file>

msg_file="$1"
first_line=$(grep -v '^#' "$msg_file" | head -n 1)

# Commits generated by Git itself are always accepted
case "$first_line" in
    "Merge "* | "Revert "* | "fixup! "* | "squash! "*) exit 0 ;;
esac

types='feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert'
pattern="^($types)(\([a-z0-9._/-]+\))?!?: .+"

if ! printf '%s\n' "$first_line" | grep -qE "$pattern"; then
    echo ""
    echo "Invalid commit message: \"$first_line\""
    echo ""
    echo "Expected format: type(optional scope): description"
    echo "Allowed types: feat, fix, docs, style, refactor, perf, test, build, ci, chore, revert"
    echo ""
    echo "Examples:"
    echo "  feat: add main menu"
    echo "  fix(parser): fix crash on empty file"
    echo ""
    exit 1
fi

if [ "${#first_line}" -gt 72 ]; then
    echo ""
    echo "The first line of the message is ${#first_line} characters long (max 72)."
    echo "Put the details in the message body, after a blank line."
    echo ""
    exit 1
fi

exit 0